package com.yeyamo_mobile.api.admin_service.event;
import java.util.*;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import com.fasterxml.jackson.databind.*;import com.yeyamo_mobile.api.admin_service.service.ValidationService;
@Component public class PartnerSubmittedConsumer{private final ObjectMapper mapper;private final ValidationService service;private final AdminProcessedEventRepository processed;public PartnerSubmittedConsumer(ObjectMapper m,ValidationService s,AdminProcessedEventRepository p){mapper=m;service=s;processed=p;}@KafkaListener(topics="${yeyamo.kafka.topics.partner-events:partner-events}",groupId="${spring.kafka.consumer.group-id:admin-service}")@Transactional public void consume(String raw)throws Exception{JsonNode event=mapper.readTree(raw);if(!"partner.submitted".equals(text(event,"eventType")))return;UUID eventId=UUID.fromString(required(event,"eventId"));if(processed.existsById(eventId))return;JsonNode payload=event.path("payload");UUID partnerId=UUID.fromString(required(payload,"partnerId"));service.createPartnerValidationFromEvent(partnerId,strings(payload,"kycDocumentKeys"),strings(payload,"kycDocumentTypes"));processed.save(new AdminProcessedEvent(eventId,"partner.submitted"));}private List<String>strings(JsonNode n,String f){JsonNode a=n.path(f);if(!a.isArray())return List.of();List<String>r=new ArrayList<>();a.forEach(v->r.add(v.asText()));return r;}private String required(JsonNode n,String f){String v=text(n,f);if(v==null||v.isBlank())throw new IllegalArgumentException(f+" is required");return v;}private String text(JsonNode n,String f){JsonNode v=n.get(f);return v==null||v.isNull()?null:v.asText();}}
